#!/usr/bin/env python3
"""Regenerates data/mapdata.js from the verbatim JSON copies in data/ (MAPS_SLICE §5: copy each JSON as is; a one-line
JS twin lets the game run from file:// without fetch). Run from the repo root after copying the JSON from design/specs.
Merge order in the game: maps_slice, interiors, act1_route2, cobblecrest, glimmer_path, mahopac, highcharity, heights, civic, town_board, fernbrook_rooms, rook_crossroads, reputation (ours, not all design copies). reputation is last
of the named files; every data/detail_*.json (map-pass overlays, ours, one file per batch) follows in sorted order. The game applies the Fernbrook door patch, then Rook's crates, after those detail patches."""
import json, pathlib
root = pathlib.Path(__file__).resolve().parent.parent / 'data'
names = ('maps_slice', 'interiors', 'act1_route2', 'cobblecrest', 'glimmer_path', 'mahopac', 'highcharity', 'heights', 'civic', 'town_board', 'fernbrook_rooms', 'rook_crossroads', 'reputation', 'moral_quests', 'starter_moment', 'news', 'ribbit_posts')
names += tuple(sorted(p.stem for p in root.glob('detail_*.json')))
names += tuple(sorted(p.stem for p in root.glob('cutscene_*.json')))   # INTRO_CUTSCENE D810: one file per staged scene
d = {k: json.loads((root / f'{k}.json').read_text()) for k in names}
(root / 'mapdata.js').write_text('// GENERATED by tools/gen_mapdata.py from data/' + ' + '.join(n + '.json' for n in names) + ' (verbatim copies of design/specs). Do not edit.\n'
                                 'const MAPDATA = ' + json.dumps(d, separators=(',', ':'), ensure_ascii=False) + ';\n')
print('wrote', root / 'mapdata.js')
# HIGH_CHARITY_LAYOUT phase 1: the city preview data stays out of MAPDATA (so save.js MAPS and normal play never see it).
# game.js merges window.PP_HC_V2 into WORLD only while HC_CITY_V2 or ?debug=1&hccity=2 is on.
hc = root / 'hc_city_v2.json'
if hc.exists():
    (root / 'hc_city_v2.js').write_text('// GENERATED by tools/gen_mapdata.py from data/hc_city_v2.json (built by tools/build_hc_city.py). Do not edit.\n'
                                        'window.PP_HC_V2 = ' + json.dumps(json.loads(hc.read_text()), separators=(',', ':'), ensure_ascii=False) + ';\n')
    print('wrote', root / 'hc_city_v2.js')
